schemas.AttemptEvent:
{
  sequence: integer
  kind: string
  payload: any JSON value
  server_time: string (RFC3339 timestamp) (optional)
}

schemas.AutomationHealth:
{
  status: string
  code: string (optional)
  message: string (optional)
}

schemas.AutomationTaskSummary:
{
  id: string
  title: string
  state: string
}

schemas.Claim:
{
  attempt: Attempt
  execution: Execution
  task: Task
  repository: Repository
}

schemas.CompleteAttemptRequest:
{
  lease_token: string
  state: string
  result: string (optional)
  error: string (optional)
}

schemas.CreateWorkflowRequest:
{
  request_key: string
  title: string
  summary: string
  instructions: string
}

schemas.GitHubIssueTrigger:
{
  type: string
  state: string
  required_labels: string[]
  poll_interval_seconds: integer
}

schemas.LegacyPollerQueueMapping:
{
  queue_id: string
  workflow_title: string
  automation_title: string
}

schemas.LegacyPollerSelection:
{
  config_path: string (optional)
  data_home: string (optional)
  working_directory: string (optional)
  confirm_stopped: boolean
}

schemas.PreviewLegacyPollerRequest:
{
  config_path: string (optional)
  data_home: string (optional)
  working_directory: string (optional)
  confirm_stopped: boolean
}

schemas.Repository:
{
  id: string
  key: string
  remote_identity: string
  retained_count: integer
}

schemas.RepositoryRegistration:
{
  key: string
  remote_identity: string
  retained_count: integer
}

schemas.ScheduleTrigger:
{
  type: string
  cron: string
  timezone: string
}

schemas.StartAttemptRequest:
{
  lease_token: string
  supervisor_pid: integer | null (optional)
  process_identity: string (optional)
  process_group_id: integer | null (optional)
}

schemas.TaskWorkflowSnapshot:
{
  id: string
  revision_id: string
  title: string
  revision_number: integer
}

schemas.TestAutomationResult:
{
  matches: AutomationMatch[]
  next_due_at: string (RFC3339 timestamp) | null (optional)
}
